package witchinggadgets;

import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.gametest.*;
import thaumcraft.aspect.*;

@GameTestHolder(WitchingGadgets.ID) @PrefixGameTestTemplate(false)
public final class SurvivalRegressionTests {
    @GameTest(template="test/platform") public static void primordialHammerMinesPlaneWithOneDurabilityCharge(GameTestHelper h){var p=GameplayTests.player(h);var pos=h.absolutePos(new BlockPos(3,2,3));for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)h.getLevel().setBlockAndUpdate(pos.offset(x,0,z),Blocks.STONE.defaultBlockState());p.moveTo(pos.getX()+.5,pos.getY()+1,pos.getZ()+.5,0,90);var hammer=Content.stack("primordial_warhammer");p.setItemInHand(InteractionHand.MAIN_HAND,hammer);h.assertTrue(p.gameMode.destroyBlock(pos),"ordinary hammer mining failed");for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)h.assertTrue(h.getLevel().isEmptyBlock(pos.offset(x,0,z)),"wrong 3x3 mining plane");h.assertValueEqual(hammer.getDamageValue(),1,"area mining charges sword durability for every sub-block");h.succeed();}
    @GameTest(template="test/platform") public static void roseVinesOnlyDropWithShears(GameTestHelper h){var p=GameplayTests.player(h);var pos=h.absolutePos(new BlockPos(3,2,3));h.getLevel().setBlockAndUpdate(pos,Content.block("rose_vines").defaultBlockState());p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.gameMode.destroyBlock(pos);h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(pos).inflate(2),e->e.getItem().is(Content.item("rose_vines"))).isEmpty(),"ordinary breaking drops a free rose vine");h.getLevel().setBlockAndUpdate(pos,Content.block("rose_vines").defaultBlockState());p.setItemInHand(InteractionHand.MAIN_HAND,Content.stack("thaumium_shears"));p.gameMode.destroyBlock(pos);h.assertValueEqual(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(pos).inflate(2),e->e.getItem().is(Content.item("rose_vines"))).stream().mapToInt(e->e.getItem().getCount()).sum(),1,"thaumium shears cannot harvest a vine");h.succeed();}
    @GameTest(template="test/platform") public static void roseGrowthUsesRandomTicksAndCreativeWand(GameTestHelper h){var p=GameplayTests.player(h);p.setGameMode(GameType.CREATIVE);var pos=h.absolutePos(new BlockPos(3,2,3));h.getLevel().setBlockAndUpdate(pos,Content.block("rose_vines").defaultBlockState());h.assertTrue(h.getLevel().getBlockState(pos).isRandomlyTicking(),"rose ignores randomTickSpeed");h.getLevel().setBlockAndUpdate(pos.above().north(),Blocks.STONE.defaultBlockState());for(int i=0;i<6;i++)GameplayTests.click(p,new ItemStack(Content.tc("wand")),pos,Direction.UP);h.assertValueEqual(((MachineEntity)h.getLevel().getBlockEntity(pos)).progress,5,"creative wand does not mature rose");h.assertTrue(h.getLevel().getBlockState(pos.above()).is(Content.block("rose_vines")),"mature rose cannot climb support wall");h.succeed();}
    @GameTest(template="test/platform") public static void voidMetalBlockWorksAsBeaconBase(GameTestHelper h){h.assertTrue(Content.block("void_metal_block").defaultBlockState().is(net.minecraft.tags.BlockTags.BEACON_BASE_BLOCKS),"void metal lost original beacon-base functionality");h.succeed();}
    @GameTest(template="test/platform") public static void capsuleCollectsWaterWithOrdinaryAirUse(GameTestHelper h){
        var p=GameplayTests.player(h);var pos=h.absolutePos(new BlockPos(3,2,3));h.getLevel().setBlockAndUpdate(pos,Blocks.WATER.defaultBlockState());p.moveTo(pos.getX()+.5,pos.getY()+1,pos.getZ()+.5,0,90);var stack=Content.stack("crystal_capsule");p.setItemInHand(InteractionHand.MAIN_HAND,stack);p.gameMode.useItem(p,h.getLevel(),stack,InteractionHand.MAIN_HAND);
        h.assertValueEqual(Data.get(p.getMainHandItem()).getInt("FluidAmount"),1000,"normal air use cannot raytrace a fluid source");h.assertTrue(h.getLevel().getFluidState(pos).isEmpty(),"capsule duplicated water");h.succeed();
    }
    @GameTest(template="test/platform") public static void capsuleDrainsWaterloggingWithoutDestroyingStairs(GameTestHelper h){
        var p=GameplayTests.player(h);var pos=h.absolutePos(new BlockPos(3,2,3));h.getLevel().setBlockAndUpdate(pos,Blocks.OAK_STAIRS.defaultBlockState().setValue(StairBlock.WATERLOGGED,true));var held=Content.stack("crystal_capsule");p.setItemInHand(InteractionHand.MAIN_HAND,held);var context=new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false));Capsule.use(context);
        h.assertTrue(h.getLevel().getBlockState(pos).is(Blocks.OAK_STAIRS)&&!h.getLevel().getBlockState(pos).getValue(StairBlock.WATERLOGGED),"capsule destroyed waterlogged structure");h.assertValueEqual(Data.get(p.getMainHandItem()).getInt("FluidAmount"),1000,"waterlogging did not fill capsule");h.succeed();
    }
    @GameTest(template="test/platform",timeoutTicks=120) public static void dispenserCollectsAndPlacesCapsuleFluidOnRedstone(GameTestHelper h){
        var pos=h.absolutePos(new BlockPos(3,2,3));var level=h.getLevel();level.setBlockAndUpdate(pos,Blocks.DISPENSER.defaultBlockState().setValue(DispenserBlock.FACING,Direction.EAST));var dispenser=(net.minecraft.world.level.block.entity.DispenserBlockEntity)level.getBlockEntity(pos);dispenser.setItem(0,Content.stack("crystal_capsule"));level.setBlockAndUpdate(pos.east(),Blocks.WATER.defaultBlockState());level.setBlockAndUpdate(pos.west(),Blocks.REDSTONE_BLOCK.defaultBlockState());
        h.runAfterDelay(8,()->{h.assertTrue(level.getFluidState(pos.east()).isEmpty(),"dispenser merely ejected empty capsule");h.assertValueEqual(Data.get(dispenser.getItem(0)).getInt("FluidAmount"),1000,"dispenser lost filled capsule");level.removeBlock(pos.west(),false);h.runAfterDelay(8,()->{level.setBlockAndUpdate(pos.west(),Blocks.REDSTONE_BLOCK.defaultBlockState());h.runAfterDelay(8,()->{h.assertTrue(level.getFluidState(pos.east()).is(net.minecraft.world.level.material.Fluids.WATER),"filled capsule cannot place through dispenser");h.assertTrue(Data.get(dispenser.getItem(0)).getInt("FluidAmount")==0,"dispenser duplicated filled capsule");h.succeed();});});});
    }
    @GameTest(template="test/platform") public static void openGauntletRechargeUpdatesTheSameSocketInventory(GameTestHelper h){
        var p=thaumcraft.test.TestSupport.mockServerPlayer(h);var glove=Content.stack("primordial_gauntlet");p.getInventory().setItem(0,glove);var node=Data.get(glove);var aspects=new net.minecraft.nbt.CompoundTag();aspects.putInt(Aspect.FIRE.name(),2);node.put("Node",aspects);Data.put(glove,node);var gem=GemItem.create(Aspect.FIRE,1,0,0);Data.integer(gem,"Spent",20);var store=new BagItem.Storage(glove,9);store.setItem(0,gem);var menu=new StorageMenu(1,p.getInventory(),glove,store,9);p.containerMenu=menu;p.tickCount=10;glove.getItem().inventoryTick(glove,h.getLevel(),p,0,true);
        h.assertValueEqual(Data.get(menu.getSlot(0).getItem()).getInt("Spent"),18,"open socket menu kept stale uncharged gem");menu.clicked(0,0,net.minecraft.world.inventory.ClickType.PICKUP,p);h.assertValueEqual(Data.get(menu.getCarried()).getInt("Spent"),18,"taking gem rewound recharge");h.assertTrue(new BagItem.Storage(glove,9).getItem(0).isEmpty(),"taking gem duplicated socket content");h.succeed();
    }
    @GameTest(template="test/platform") public static void ovalElementCannotPlaceWaterOrFireInEmptySky(GameTestHelper h){var p=h.makeMockPlayer(GameType.SURVIVAL);p.moveTo(h.absolutePos(new BlockPos(3,20,3)).getCenter());p.setXRot(-90);var water=GemItem.create(Aspect.WATER,1,0,0);h.assertTrue(!GemItem.activate(water,p,false)&&Data.get(water).getInt("Spent")==0,"water gem works without a block target");var fire=GemItem.create(Aspect.FIRE,1,0,0);h.assertTrue(!GemItem.activate(fire,p,false),"fire gem creates unsupported sky fire");h.succeed();}
}
